19	/**
20	 * Builds the URL hash used for deep-linking to an eval output details dialog.
21	 * Public URLs use one-based row/prompt numbers while the UI uses zero-based indexes internally.
22	 */
23	export function buildEvalOutputPromptHash(rowIndex: number, promptIndex: number): string {
24	  return `#details-row-${rowIndex + 1}-prompt-${promptIndex + 1}`;
