27	/**
28	 * Parses an eval output details hash into zero-based row/prompt indexes.
29	 */
30	export function parseEvalOutputPromptHash(hash: string): EvalOutputPromptHashTarget | null {
31	  const match = hash.match(EVAL_OUTPUT_PROMPT_HASH_PATTERN);
32	  if (!match) {
33	    return null;
34	  }
35	
36	  const rowNumber = Number.parseInt(match[1], 10);
37	  const promptNumber = Number.parseInt(match[2], 10);
38	
39	  if (rowNumber < 1 || promptNumber < 1) {
40	    return null;
41	  }
42	
43	  return {
44	    rowIndex: rowNumber - 1,
45	    promptIndex: promptNumber - 1,
46	  };
47	}
