81	/**
82	 * Shared subscription for the URL hash that the eval-output details dialogs use as a deep
83	 * link. We need a single source of truth because:
84	 *   1. `history.replaceState` (used by the dialog open/close handlers) does not fire
85	 *      `hashchange`, so per-component listeners would go stale silently.
86	 *   2. Tables can render thousands of cells; one global listener is much cheaper than one
87	 *      listener per cell.
88	 *
89	 * Components subscribe via `useEvalDetailsHash()`. Code that mutates the hash should call
90	 * `setEvalDetailsHash()`, which performs the `replaceState` and notifies subscribers.
91	 */
92	const evalDetailsHashListeners = new Set<() => void>();
93	
94	function notifyEvalDetailsHashListeners(): void {
95	  for (const cb of evalDetailsHashListeners) {
96	    cb();
97	  }
98	}
