100	if (typeof window !== 'undefined') {
101	  // Covers direct address-bar edits and back/forward navigation. `replaceState` is handled
102	  // explicitly by `setEvalDetailsHash`.
103	  window.addEventListener('hashchange', notifyEvalDetailsHashListeners);
104	}
