117	export function setEvalDetailsHash(hash: string, rowPositionIndex?: number): void {
118	  if (typeof window === 'undefined') {
119	    return;
120	  }
121	  const next = hash ? (hash.startsWith('#') ? hash : `#${hash}`) : '';
122	  const url = new URL(window.location.href);
123	  if (rowPositionIndex !== undefined) {
124	    url.searchParams.set('rowId', String(rowPositionIndex + 1));
125	  } else if (!next) {
126	    url.searchParams.delete('rowId');
127	  }
128	  url.hash = next;
129	  if (url.href === window.location.href) {
130	    return;
131	  }
132	  window.history.replaceState(window.history.state, '', url);
