import { renderWithProviders } from '@app/utils/testutils';
import { act, screen, waitFor } from '@testing-library/react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import ResultsTable from './ResultsTable';
import { useResultsViewSettingsStore, useTableStore } from './store';

vi.mock('./store', () => ({
  useTableStore: vi.fn(),
  useResultsViewSettingsStore: vi.fn(() => ({ inComparisonMode: false, renderMarkdown: true })),
}));
vi.mock('@app/hooks/useToast', () => ({ useToast: vi.fn(() => ({ showToast: vi.fn() })) }));
vi.mock('@app/hooks/useShiftKey', () => ({
  ShiftKeyContext: { Provider: ({ children }: any) => children },
  useShiftKey: vi.fn(() => false),
}));
vi.mock('@app/utils/api', () => ({ callApi: vi.fn(() => Promise.resolve({ ok: true })) }));
const mockNavigate = vi.fn();
vi.mock('react-router-dom', async () => ({
  ...(await vi.importActual('react-router-dom')),
  useNavigate: () => mockNavigate,
}));
vi.mock('./EvalOutputCell', () => ({
  __esModule: true,
  default: vi.fn(({ rowIndex }: any) => <div data-testid="eval-output-cell" data-rowindex={rowIndex} />),
}));

const defaultProps = {
  columnVisibility: {},
  failureFilter: {},
  filterMode: 'all' as const,
  maxTextLength: 100,
  onFailureFilterToggle: vi.fn(),
  showStats: true,
  wordBreak: 'break-word' as const,
  zoom: 1,
};

function setup(url: string, filteredResultsCount = 120) {
  window.history.replaceState({}, '', url);
  const fetchEvalData = vi.fn();
  vi.mocked(useResultsViewSettingsStore).mockImplementation(() => ({
    inComparisonMode: false,
    renderMarkdown: true,
  }));
  vi.mocked(useTableStore).mockImplementation(() => ({
    config: {},
    evalId: '123',
    setTable: vi.fn(),
    table: {
      body: [{ outputs: [{ id: 'x', pass: true, score: 1, text: 'o', originalRowIndex: 0 }], test: {}, testIdx: 0, vars: [] }],
      head: { prompts: [{}], vars: [] },
    },
    version: 4,
    fetchEvalData,
    filteredResultsCount,
    totalResultsCount: 120,
    filters: { values: {}, appliedCount: 0, options: { metric: [] } },
  }));
  return fetchEvalData;
}

describe('deep-link filter behavior', () => {
  afterEach(() => {
    window.history.replaceState({}, '', '/');
    mockNavigate.mockReset();
  });

  it('req1/2: filter active + hash-only -> no page nav, hash preserved', async () => {
    const fetchEvalData = setup('/#details-row-51-prompt-1');
    renderWithProviders(<ResultsTable {...defaultProps} filterMode="failures" />);
    await act(async () => { await Promise.resolve(); });
    expect(fetchEvalData).not.toHaveBeenCalledWith('123', expect.objectContaining({ pageIndex: 1 }));
    expect(window.location.hash).toBe('#details-row-51-prompt-1');
  });

  it('req4: filter active + rowId -> page nav', async () => {
    const fetchEvalData = setup('/?rowId=51');
    renderWithProviders(<ResultsTable {...defaultProps} filterMode="failures" />);
    await waitFor(() => {
      expect(fetchEvalData).toHaveBeenCalledWith('123', expect.objectContaining({ pageIndex: 1, pageSize: 50 }));
    });
  });

  it('req3: no filter + hash -> page nav', async () => {
    const fetchEvalData = setup('/#details-row-51-prompt-1');
    renderWithProviders(<ResultsTable {...defaultProps} filterMode="all" />);
    await waitFor(() => {
      expect(fetchEvalData).toHaveBeenCalledWith('123', expect.objectContaining({ pageIndex: 1, pageSize: 50 }));
    });
  });

  it('req5: removing filter clears hash and does not nav', async () => {
    const fetchEvalData = setup('/#details-row-51-prompt-1');
    const { rerender } = renderWithProviders(<ResultsTable {...defaultProps} filterMode="failures" />);
    await act(async () => { await Promise.resolve(); });
    fetchEvalData.mockClear();
    rerender(<ResultsTable {...defaultProps} filterMode="all" />);
    await act(async () => { await Promise.resolve(); });
    expect(window.location.hash).toBe('');
    expect(fetchEvalData).not.toHaveBeenCalledWith('123', expect.objectContaining({ pageIndex: 1 }));
  });

  it('req6: removing filter after rowId consumed clears search and fetches pageIndex 0', async () => {
    const fetchEvalData = setup('/?rowId=51');
    const { rerender } = renderWithProviders(<ResultsTable {...defaultProps} filterMode="failures" />);
    await waitFor(() => {
      expect(fetchEvalData).toHaveBeenCalledWith('123', expect.objectContaining({ pageIndex: 1 }));
    });
    fetchEvalData.mockClear();
    rerender(<ResultsTable {...defaultProps} filterMode="all" />);
    await waitFor(() => {
      expect(fetchEvalData).toHaveBeenCalledWith('123', expect.objectContaining({ pageIndex: 0 }));
    });
    expect(window.location.search).toBe('');
  });

  it('req7: StrictMode deep-link nav works and hash preserved', async () => {
    const fetchEvalData = setup('/#details-row-51-prompt-1');
    renderWithProviders(
      <StrictMode>
        <ResultsTable {...defaultProps} filterMode="all" />
      </StrictMode>,
    );
    await waitFor(() => {
      expect(fetchEvalData).toHaveBeenCalledWith('123', expect.objectContaining({ pageIndex: 1, pageSize: 50 }));
    });
    expect(window.location.hash).toBe('#details-row-51-prompt-1');
  });
});
